export function formatWeight(kg: number): string {
  if (kg < 1) {
    return Math.round(kg * 1000) + " g";
  }
  return kg.toFixed(1) + " kg";
}

export function formatVolume(litres: number): string {
  if (litres > 1000) {
    return (litres / 1000).toFixed(2) + " m³";
  }
  return litres + " l";
}
