import { formatWeight } from "./format";
import { statusLabel, type Status } from "./status";

interface Parcel {
  weight: number;
  status: Status;
}

const parcels: Record<string, Parcel> = {
  "PX-1042": { weight: 0.4, status: "in_transit" },
  "PX-2077": { weight: 12.5, status: "delivered" },
};

function track(code: string): string {
  const parcel = parcels[code];
  if (!parcel) {
    return "No parcel " + code;
  }
  return statusLabel(parcel.status) + ", " + formatWeight(parcel.weight);
}

document.getElementById("track")!.addEventListener("click", () => {
  const code = (document.getElementById("code") as HTMLInputElement).value;
  document.getElementById("result")!.textContent = track(code);
});
